medium.code:
console.log(1);

setTimeout(() => {
  console.log(2);
  Promise.resolve().then(() => console.log(3));
}, 0);

Promise.resolve()
  .then(() => console.log(4))
  .then(() => console.log(5));

console.log(6);

Promise.resolve()
  .then(() => {
    console.log(1);
    return Promise.resolve();
  })
  .then(() => console.log(2));

setTimeout(() => console.log(3), 0);

hard.code:
async function test() {
  console.log(1);
  await Promise.resolve();
  console.log(2);
}

test();
console.log(3);
